const html=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kinds={text:'Testo',document:'Documento',url:'Pagina web','folder-file':'File locale',github:'GitHub pubblico',research:'Ricerca web AI'};
const date=value=>{const d=new Date(value);return value&&Number.isFinite(d.getTime())?new Intl.DateTimeFormat('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(d):'—';};
const safeUrl=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}};
const link=(url,title)=>safeUrl(url)?`<a href="${html(safeUrl(url))}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">${html(title||url)} ↗</a>`:`<span>${html(title||url)}</span>`;
function citationText(value,citations=[]) {
  const allowed=new Set(citations.map(item=>safeUrl(item.url)).filter(Boolean));
  const text=String(value??''),pattern=/\[([^\]\n]{1,500})\]\((https:\/\/[^\s)]+)\)/g;let cursor=0,result='';
  for(const match of text.matchAll(pattern)){result+=html(text.slice(cursor,match.index));result+=allowed.has(safeUrl(match[2]))?link(match[2],match[1]):html(match[0]);cursor=match.index+match[0].length;}
  return result+html(text.slice(cursor));
}
const help=(label,text)=>`<details class="source-help"><summary aria-label="Aiuto: ${html(label)}">?</summary><p>${html(text)}</p></details>`;
const bytes=value=>Number.isFinite(value)?value<1024?`${value} B`:value<1048576?`${Math.round(value/1024)} KiB`:`${(value/1048576).toFixed(1)} MiB`:'—';

export function createSourcesPanel({host,toast=()=>{},onProviders=()=>{},onCount=()=>{},onChanged=()=>{}}={}) {
  let context={scopeId:'business',scopes:[],providers:{connections:[],policies:{}}},snapshot={sources:[],connectors:[],limits:{}},loadedScope=null,visible=false,loading=false,saving=false,busy=false,error='',generation=0,disposed=false,view=null,filter='';
  const dialog=document.createElement('dialog');dialog.id='sources-dialog';dialog.className='ops-dialog source-dialog';dialog.setAttribute('aria-labelledby','source-dialog-title');document.body.append(dialog);
  const scopeName=id=>context.scopes.find(scope=>scope.id===id)?.name||id;
  const connector=id=>snapshot.connectors.find(item=>item.id===id);
  const sourceFor=id=>snapshot.sources.find(item=>item.id===id);
  const locked=()=>busy||loading||saving||disposed||loadedScope!==context.scopeId;
  function allowedConnections(){const policy=context.providers.policies?.[context.scopeId]||[];return (context.providers.connections||[]).filter(connection=>connection.type==='openai'&&connection.configured&&policy.includes(connection.id));}
  async function request(path,body){if(disposed)throw Error('Sessione scaduta.');const response=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json','X-Fuori-Studio':'local'},body:JSON.stringify(body)}:{cache:'no-store'});let value;try{value=await response.json();}catch{throw Error('Le fonti non sono disponibili. Riprova.');}if(disposed)throw Error('Sessione scaduta.');if(!response.ok){const e=Error(value.error||'Non è stato possibile completare la richiesta.');e.status=response.status;throw e;}return value;}
  async function load(){const current=++generation,scopeId=context.scopeId;if(disposed)return;loading=true;error='';if(loadedScope!==scopeId)onCount('…');render();try{const value=await request(`/api/sources?scopeId=${encodeURIComponent(scopeId)}`);if(current!==generation||scopeId!==context.scopeId)return;if(!Array.isArray(value.sources)||!Array.isArray(value.connectors))throw Error('I dati delle fonti non sono validi.');snapshot=value;loadedScope=scopeId;loading=false;onCount(value.sources.length);render();}catch(e){if(current!==generation)return;loading=false;error=e.message;render();}finally{locks();}}
  function locks(){host.querySelectorAll('[data-source-mutation]').forEach(el=>el.disabled=locked()||(el.dataset.sourceAction==='research'&&(!connector('research')?.enabled||!allowedConnections().length)));dialog.querySelectorAll('[data-source-mutation],button[type="submit"]').forEach(el=>el.disabled=locked());}
  function render(){if(!visible)return;const sources=snapshot.sources.filter(source=>!filter||`${source.title} ${source.filename||''} ${source.url||''}`.toLocaleLowerCase('it').includes(filter));
    host.innerHTML=`<div class="source-heading"><div><div class="source-title-row"><h3>I materiali del tuo lavoro.</h3>${help('Fonti e ambiti','Le fonti rimangono nell’ambito scelto, senza condivisioni automatiche. I passaggi aggiornati possono essere recuperati come materiale per gli agenti. Testi, pagine e risultati AI sono dati da valutare, non istruzioni o memorie confermate.')}</div><p>Ambito: <strong>${html(scopeName(context.scopeId))}</strong>. Documenti, pagine e ricerche con una provenienza consultabile.</p></div><button type="button" class="ops-button" data-source-action="reload"${loading?' disabled':''}>${loading?'Caricamento…':'Aggiorna elenco'}</button></div><div class="source-tools"><button type="button" class="ops-button is-primary" data-source-action="text" data-source-mutation>Incolla testo</button><button type="button" class="ops-button" data-source-action="document" data-source-mutation>Carica documento</button><button type="button" class="ops-button" data-source-action="url" data-source-mutation>Pagina o GitHub</button>${connector('folders')?.enabled?'<button type="button" class="ops-button" data-source-action="folder" data-source-mutation>Cartella locale</button>':''}<button type="button" class="ops-button" data-source-action="research" data-source-mutation>Ricerca web AI</button></div>${connector('research')?.enabled&&!allowedConnections().length?'<p class="source-notice">Per la ricerca web serve una connessione OpenAI API configurata e consentita in questo ambito. <button type="button" class="ops-text-button" data-source-action="providers">Apri Servizi AI ↗</button></p>':''}${error?`<p class="ops-error" role="alert">${html(error)}</p>`:''}${loading?'<p class="source-empty" role="status">Caricamento dei materiali dell’ambito…</p>':snapshot.sources.length?`<label class="source-filter"><span class="visually-hidden">Cerca tra le fonti salvate</span><input type="search" id="source-filter" placeholder="Cerca tra le fonti salvate…" value="${html(filter)}" maxlength="200" autocomplete="off"></label><div class="source-grid">${sources.map(source=>`<article class="source-card"><div class="source-card-top"><span>${html(kinds[source.kind]||source.kind)}</span><span class="source-state${source.status==='stale'?' is-stale':''}">${source.status==='stale'?'Da aggiornare':'Aggiornata'}</span></div><h3>${html(source.title)}</h3><p>${html(source.filename||source.url||'Contenuto acquisito nello studio')}</p><div class="source-facts"><span>${source.segmentCount} passaggi · ${bytes(source.bytes)}</span><span>v${source.version} · ${html(date(source.retrievedAt))}</span></div>${source.status==='stale'?'<p class="source-stale-note">Esclusa dal contesto finché non viene aggiornata.</p>':''}<div class="source-card-actions"><button type="button" class="ops-button" data-source-action="detail" data-id="${html(source.id)}">Leggi fonte ↗</button>${source.refreshable?`<button type="button" class="ops-text-button" data-source-action="refresh" data-id="${html(source.id)}" data-source-mutation>Aggiorna contenuto</button>`:''}</div></article>`).join('')||'<p class="source-empty">Nessuna fonte corrisponde alla ricerca.</p>'}</div>`:'<div class="source-empty"><span aria-hidden="true">▤</span><h3>Porta qui i materiali del progetto.</h3><p>Incolla un testo, carica un documento o acquisisci una pagina pubblica. Potrai leggere ogni passaggio insieme alla sua provenienza.</p></div>'}<details class="source-connectors"><summary>Strumenti disponibili e limiti</summary><div>${snapshot.connectors.map(item=>`<article><div><strong>${html(item.name)}</strong><span>${item.enabled?'Disponibile · sola lettura':'Non disponibile qui'}</span></div><p>${html(item.limitations)}</p></article>`).join('')}</div></details><p class="source-footnote">Le fonti non diventano automaticamente memorie. Per cambiare ambito usa il selettore della conversazione.</p>`;
    host.querySelector('#source-filter')?.addEventListener('input',event=>{const start=event.target.selectionStart;filter=event.target.value.toLocaleLowerCase('it');render();const input=host.querySelector('#source-filter');input.focus({preventScroll:true});try{input.setSelectionRange(start,start);}catch{}});locks();
  }
  function shell(title,body,footer){dialog.innerHTML=`<div class="ops-dialog-heading"><div><div class="eyebrow">FONTI DELLO STUDIO</div><h2 id="source-dialog-title">${html(title)}</h2></div><button type="button" class="ops-icon" data-source-close aria-label="Chiudi finestra">✕</button></div>${body}<div class="ops-dialog-footer">${footer||'<button type="button" class="ops-button" data-source-close>Chiudi</button>'}</div>`;if(!dialog.open)dialog.showModal();locks();}
  function field(label,name,value='',{area=false,required=true,max=200,type='text'}={}){return `<div class="ops-field"><label for="source-field-${name}">${html(label)}</label>${area?`<textarea id="source-field-${name}" name="${name}" rows="6" maxlength="${max}"${required?' required':''}>${html(value)}</textarea>`:`<input id="source-field-${name}" name="${name}" type="${type}" value="${html(value)}" maxlength="${max}"${required?' required':''} autocomplete="off">`}</div>`;}
  function form(title,body,label,submit){const scopeId=context.scopeId;view={kind:'form',scopeId};shell(title,`<form id="source-form"><div class="ops-form-body"><p class="ops-form-intro">Destinazione: <strong>${html(scopeName(scopeId))}</strong>. Disponibile soltanto in questo ambito.</p>${body}</div><p class="ops-form-error" role="alert" hidden></p></form>`,`<button type="button" class="ops-button" data-source-close>Annulla</button><button type="submit" form="source-form" class="ops-button is-primary" data-source-mutation>${html(label)}</button>`);
    dialog.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();if(locked())return;const el=event.currentTarget;if(!el.reportValidity())return;const data=new FormData(el),box=dialog.querySelector('.ops-form-error'),button=dialog.querySelector('[type="submit"]');saving=true;box.hidden=true;button.textContent='Elaborazione in corso…';locks();try{const result=await submit(data,scopeId);await load();onChanged();saving=false;dialog.close();if(context.scopeId===scopeId){if(result?.source)showDetail(result);else if(result?.imported)showFolderResult(result);}toast(`Fonti aggiornate in ${scopeName(scopeId)}.`);}catch(e){box.textContent=e.status===409?`${e.message} Ricarica l’elenco e riapri la fonte per usare la versione corrente.`:e.message;box.hidden=false;button.textContent=label;}finally{saving=false;locks();}});
  }
  function textForm(){form('Aggiungi un testo',`${field('Titolo della fonte','title')}${field('Testo da conservare come materiale','text','',{area:true,max:snapshot.limits.maxTextChars||600000})}<p class="ops-hint">Il testo resta una fonte consultabile. Non viene salvato come memoria confermata.</p>`,'Acquisisci testo',(data,scopeId)=>request('/api/sources',{action:'importText',payload:{scopeId,title:data.get('title').trim(),text:data.get('text').trim()}}));}
  function documentForm(){form('Carica un documento',`${field('Titolo della fonte','title')}<div class="ops-field"><label for="source-document">Documento</label><input id="source-document" type="file" name="document" accept=".pdf,.txt,.md,.markdown,.html,.json,application/pdf,text/plain,text/markdown" required><p class="ops-hint">PDF con testo, TXT, Markdown, HTML o JSON · massimo ${bytes(snapshot.limits.maxDocumentBytes||8388608)}. PDF fino a 200 pagine, senza OCR per scansioni.</p></div><p class="source-notice">Lo studio conserva il testo estratto e la provenienza. Il file originale non viene offerto come download dell’archivio.</p>`,'Importa documento',async(data,scopeId)=>{const file=data.get('document');if(!(file instanceof File)||!file.size)throw Error('Scegli un file non vuoto.');if(file.size>(snapshot.limits.maxDocumentBytes||8388608))throw Error('Il documento supera il limite. Suddividilo in file più piccoli.');const dataBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Il file non può essere letto.'));reader.readAsDataURL(file);});return request('/api/sources',{action:'importDocument',payload:{scopeId,title:data.get('title').trim(),filename:file.name,mimeType:file.type||'text/plain',dataBase64}});});dialog.querySelector('[name="document"]').addEventListener('change',event=>{const title=dialog.querySelector('[name="title"]');if(!title.value&&event.target.files[0])title.value=event.target.files[0].name.replace(/\.[^.]+$/,'').slice(0,200);});}
  function urlForm(){form('Acquisisci una pagina pubblica',`${field('URL HTTPS pubblico','url','',{type:'url',max:2048})}${field('Titolo · facoltativo','title','',{required:false})}<p class="source-notice">Acquisisce una pagina statica pubblica, senza login o esplorazione automatica dei link. Per GitHub sono supportati i metadati di una repository pubblica e il testo di una singola issue: commenti e repository privati restano esclusi.</p><p class="ops-hint">La richiesta contatta il sito indicato. Potrai aggiornare manualmente il contenuto e controllarne la versione.</p>`,'Acquisisci pagina',(data,scopeId)=>{const url=data.get('url').trim();if(!url.startsWith('https://'))throw Error('Inserisci un URL pubblico che inizi con https://.');return request('/api/sources',{action:'importUrl',payload:{scopeId,url,...(data.get('title').trim()?{title:data.get('title').trim()}:{})}});});}
  function folderForm(){form('Acquisisci una cartella locale',`${field('Percorso della cartella sul computer dello studio','path','',{max:2000})}<p class="source-notice">Solo cartelle sotto le radici autorizzate: repository registrate o percorsi configurati nello studio. La lettura esclude file sensibili, collegamenti simbolici, dipendenze e cartelle generate.</p><p class="ops-hint">Importa fino a ${snapshot.limits.maxFolderFiles||60} file testuali entro i limiti del server. Al termine vedrai file acquisiti ed esclusi con il motivo. Non esegue i file e non segue modifiche automaticamente.</p>`,'Acquisisci cartella',(data,scopeId)=>request('/api/sources',{action:'importFolder',payload:{scopeId,path:data.get('path').trim()}}));}
  function researchForm(){const connections=allowedConnections();if(!connections.length){toast('Configura e autorizza una connessione OpenAI API per questo ambito.');return;}form('Una ricerca con fonti da controllare',`${field('Domanda di ricerca','query','',{area:true,max:4000})}<div class="ops-field"><label for="source-research-connection">Connessione OpenAI API autorizzata</label><select id="source-research-connection" name="connectionId" required>${connections.map(connection=>`<option value="${html(connection.id)}">${html(connection.name)} · ${html(connection.model)}</option>`).join('')}</select></div>${field('Limita ai domini · facoltativo','domains','',{required:false,max:2600})}<p class="ops-hint">Al massimo 10 domini separati da virgole, ad esempio openai.com, github.com. Lascia vuoto per non applicare questo filtro.</p><label class="ops-check source-consent"><input type="checkbox" name="consent" required><span>Autorizzo questa ricerca web a consumo<small>Invia la domanda al servizio OpenAI API selezionato e usa la ricerca web. Può generare costi sul relativo account. Non usa l’accesso Codex come alternativa.</small></span></label><p class="source-notice">Il risultato AI viene conservato come fonte, con i link restituiti da controllare. Non è una memoria verificata e diventerà da aggiornare alla sua scadenza.</p>`,'Esegui ricerca web a consumo',(data,scopeId)=>{if(!data.has('consent'))throw Error('Conferma l’invio di questa ricerca.');const domains=data.get('domains').split(',').map(value=>value.trim()).filter(Boolean);if(domains.length>10||domains.some(value=>!(/^[a-zA-Z0-9.-]+$/).test(value)))throw Error('Indica al massimo 10 domini, senza URL, percorsi o spazi.');return request('/api/sources',{action:'searchWeb',payload:{scopeId,connectionId:data.get('connectionId'),query:data.get('query').trim(),...(domains.length?{domains}:{}),consent:true}});});}
  function showFolderResult(result){view={kind:'result',scopeId:context.scopeId};shell('La cartella, file per file',`<div class="ops-task-body"><div class="source-import-counts"><span><b>${result.imported.length}</b> acquisiti</span><span><b>${result.skipped?.length||0}</b> esclusi</span></div><div class="source-folder-results">${result.imported.map(item=>`<article><strong>${html(item.title||item.filename)}</strong><span>Acquisito · ${item.segmentCount} passaggi</span></article>`).join('')}${(result.skipped||[]).map(item=>`<article class="is-skipped"><strong>${html(item.path)}</strong><span>${html(item.reason)}</span></article>`).join('')}</div></div>`);}
  function locator(segment){return [segment.page?`Pagina ${segment.page}`:'',segment.lineStart?`Righe ${segment.lineStart}${segment.lineEnd&&segment.lineEnd!==segment.lineStart?`–${segment.lineEnd}`:''}`:''].filter(Boolean).join(' · ')||'Passaggio';}
  function renderPassages(){if(view?.kind!=='detail')return;const query=dialog.querySelector('#source-passage-filter').value.toLocaleLowerCase('it'),segments=view.detail.segments.filter(item=>!query||item.text.toLocaleLowerCase('it').includes(query));dialog.querySelector('#source-passages').innerHTML=segments.slice(0,view.limit).map(segment=>`<article><div><strong>${html(locator(segment))}</strong><code>${html(segment.id)}</code></div><p>${citationText(segment.text,view.detail.citationSources)}</p></article>`).join('')||'<p class="source-empty">Nessun passaggio corrisponde alla ricerca.</p>';dialog.querySelector('#source-passage-count').textContent=`${Math.min(view.limit,segments.length)} di ${segments.length} passaggi`;dialog.querySelector('[data-source-action="more-passages"]').hidden=segments.length<=view.limit;}
  function showDetail(detail){const source=detail.source;if(!source||!Array.isArray(detail.segments))throw Error('Questa fonte non contiene passaggi leggibili.');view={kind:'detail',scopeId:source.scopeId,detail,limit:20};shell(source.title,`<div class="ops-task-body source-detail-body"><div class="source-detail-meta"><span class="source-state${source.status==='stale'?' is-stale':''}">${source.status==='stale'?'Da aggiornare · esclusa dal contesto':'Aggiornata'}</span><span>${html(kinds[source.kind])} · ${html(scopeName(source.scopeId))} · v${source.version}</span></div>${source.status==='stale'?`<p class="source-notice">Questa versione è scaduta e non viene recuperata per gli agenti. ${source.refreshable?'Aggiorna il contenuto dalla fonte originale.':'Importa materiale aggiornato o esegui una nuova ricerca esplicita.'}</p>`:''}<details class="source-provenance"><summary>Provenienza e versione</summary><dl><div><dt>Acquisita</dt><dd>${html(date(source.retrievedAt))}</dd></div><div><dt>Scadenza</dt><dd>${source.staleAt?html(date(source.staleAt)):'Nessuna scadenza automatica'}</dd></div>${source.filename?`<div><dt>File</dt><dd>${html(source.filename)}</dd></div>`:''}${source.url?`<div><dt>Origine</dt><dd>${link(source.url)}</dd></div>`:''}<div><dt>Impronta del contenuto</dt><dd><code>${html(source.digest)}</code></dd></div></dl></details>${detail.citationSources?.length?`<section class="source-citations"><h3>Fonti restituite dalla ricerca</h3><ul>${detail.citationSources.map(item=>`<li>${link(item.url,item.title)}</li>`).join('')}</ul><p>Apri i link e verifica le affermazioni nel loro contesto originale.</p></section>`:''}<div class="source-passages-toolbar"><label><span class="visually-hidden">Cerca nel testo acquisito</span><input type="search" id="source-passage-filter" placeholder="Cerca nel testo acquisito…" maxlength="200" autocomplete="off"></label><span id="source-passage-count"></span></div><div id="source-passages" class="source-passages"></div><button type="button" class="ops-button" data-source-action="more-passages">Mostra altri 20 passaggi</button><p class="source-footnote">Il testo viene mostrato come materiale da leggere; link o istruzioni presenti nel contenuto non vengono eseguiti.</p></div>`,`<button type="button" class="ops-button" data-source-close>Chiudi</button><button type="button" class="ops-button" data-source-action="remove" data-id="${html(source.id)}" data-source-mutation>Rimuovi fonte</button>${source.refreshable?`<button type="button" class="ops-button is-primary" data-source-action="refresh" data-id="${html(source.id)}" data-source-mutation>Aggiorna contenuto</button>`:''}`);dialog.querySelector('#source-passage-filter').addEventListener('input',()=>{view.limit=20;renderPassages();});renderPassages();}
  async function openDetail(source){const scopeId=context.scopeId,current=generation;try{const value=await request(`/api/sources/detail?scopeId=${encodeURIComponent(scopeId)}&id=${encodeURIComponent(source.id)}`);if(scopeId===context.scopeId&&current===generation)showDetail(value);}catch(e){toast(e.message);}}
  async function refresh(source){if(locked())return;saving=true;locks();const scopeId=context.scopeId;try{const value=await request('/api/sources',{action:'refresh',payload:{scopeId,id:source.id,version:source.version}});await load();onChanged();saving=false;if(scopeId===context.scopeId)showDetail(value);toast('Fonte aggiornata con una nuova versione.');}catch(e){toast(e.message);}finally{saving=false;locks();}}
  function remove(source){form('Rimuovi questa fonte',`<p><strong>${html(source.title)}</strong> · versione ${source.version}</p><p>Rimuove il testo acquisito da questo ambito. Non elimina il file o la pagina originale.</p>`,'Rimuovi dallo studio',(_data,scopeId)=>request('/api/sources',{action:'remove',payload:{scopeId,id:source.id,version:source.version}}));}
  function click(event){if(event.target.closest('[data-source-close]')){if(!saving)dialog.close();return;}const button=event.target.closest('[data-source-action]');if(!button||button.disabled)return;const action=button.dataset.sourceAction;if(action==='reload'){void load();return;}if(action==='providers'){onProviders();return;}if(action==='more-passages'){if(view?.kind==='detail'){view.limit+=20;renderPassages();}return;}const source=sourceFor(button.dataset.id)||view?.detail?.source;if(action==='detail'&&source){void openDetail(source);return;}if(locked())return;if(action==='text')textForm();if(action==='document')documentForm();if(action==='url')urlForm();if(action==='folder'&&connector('folders')?.enabled)folderForm();if(action==='research'&&connector('research')?.enabled)researchForm();if(action==='refresh'&&source?.refreshable)void refresh(source);if(action==='remove'&&source)remove(source);}
  host.addEventListener('click',click);dialog.addEventListener('click',click);dialog.addEventListener('cancel',event=>{if(saving)event.preventDefault();});dialog.addEventListener('close',()=>{if(!dialog.open)view=null;});
  function expire(){disposed=true;generation++;if(dialog.open)dialog.close();}window.addEventListener('studio-session-expired',expire);
  return {load,setContext(value){const changed=value.scopeId&&value.scopeId!==context.scopeId;context={...context,...value};if(changed){generation++;loadedScope=null;snapshot={sources:[],connectors:[],limits:{}};filter='';onCount('…');if(dialog.open&&!saving)dialog.close();void load();}render();},setVisible(value){const changed=value&&!visible;visible=Boolean(value);host.hidden=!visible;render();if(changed&&loadedScope!==context.scopeId&&!loading)void load();},setBusy(value){busy=Boolean(value);locks();},dispose(){expire();window.removeEventListener('studio-session-expired',expire);host.removeEventListener('click',click);dialog.remove();}};
}
